package com.nthexperience.desktop;
import org.json.*;import java.net.URI;import java.util.*;
/** Official display-only embed configuration; quotes are never extracted, cached or synthesized. */
final class ElevenMarket {
 static final String ENABLED="eleven_market_enabled",MODE="eleven_market_mode",RANGE="eleven_market_range";
 static final List<String> MODES=Arrays.asList("Index ETFs","Indices"),RANGES=Arrays.asList("1D","1M","3M","12M","60M","ALL");
 static String mode(String value){return MODES.contains(value)?value:"Index ETFs";}static String range(String value){return RANGES.contains(value)?value:"1D";}
 static String report(String mode,int at){String[] paths=mode(mode).equals("Indices")?new String[]{"SP-SPX","NASDAQ-IXIC","TVC-DJI","TVC-RUT"}:new String[]{"AMEX-SPY","NASDAQ-QQQ","AMEX-DIA","AMEX-IWM"};return "https://www.tradingview.com/symbols/"+paths[Math.max(0,Math.min(3,at))]+"/";}
 static boolean safeLink(String value){try{URI u=new URI(value);return "https".equalsIgnoreCase(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 static String html(boolean light,String selected,String period){try{boolean indices=mode(selected).equals("Indices");String[] symbols=indices?new String[]{"SP:SPX","NASDAQ:IXIC","TVC:DJI","TVC:RUT"}:new String[]{"AMEX:SPY","NASDAQ:QQQ","AMEX:DIA","AMEX:IWM"};String[] names=indices?new String[]{"S&P 500","Nasdaq Composite","Dow Jones","Russell 2000"}:new String[]{"S&P 500 ETF (SPY)","Nasdaq 100 ETF (QQQ)","Dow ETF (DIA)","Russell 2000 ETF (IWM)"};JSONArray rows=new JSONArray();for(int i=0;i<4;i++)rows.put(new JSONObject().put("s",symbols[i]).put("d",names[i]));JSONObject config=new JSONObject().put("colorTheme",light?"light":"dark").put("dateRange",range(period)).put("showChart",true).put("locale","en").put("width","100%").put("height",430).put("isTransparent",false).put("showSymbolLogo",false).put("tabs",new JSONArray().put(new JSONObject().put("title",indices?"US indices":"Index ETFs").put("symbols",rows)));
 return "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='referrer' content='no-referrer'><style>html,body{margin:0;padding:0;background:"+(light?"#fdfdff":"#2c2d3c")+";color:"+(light?"#202029":"#f2f2f2")+";font:13px sans-serif}a{color:"+(light?"#0756aa":"#9accff")+"}.tradingview-widget-copyright{font-size:13px;text-align:center;padding:5px 0}#problem{padding:12px}</style></head><body><div class='tradingview-widget-container'><div class='tradingview-widget-container__widget'></div><div class='tradingview-widget-copyright'><a href='https://www.tradingview.com/markets/' rel='noopener nofollow' target='_blank'><span class='blue-text'>World markets</span></a><span class='trademark'> by TradingView</span></div><script type='text/javascript' src='https://s3.tradingview.com/external-embedding/embed-widget-market-overview.js' async onerror='document.getElementById(&quot;problem&quot;).hidden=false'>"+config+"</script></div><p id='problem' hidden>The market provider could not load. Use Retry or open a report below.</p><script>setTimeout(function(){if(!document.querySelector('iframe'))document.getElementById('problem').hidden=false;},15000);</script></body></html>";
 }catch(JSONException e){throw new IllegalStateException(e);}}
 static void validate(Map<String,Object> values)throws JSONException{if(values.containsKey(MODE)&&!MODES.contains(values.get(MODE)))throw new JSONException("Invalid market symbols");if(values.containsKey(RANGE)&&!RANGES.contains(values.get(RANGE)))throw new JSONException("Invalid market range");}
 private ElevenMarket(){}
}
